/* the wall: every bulb flickers on its own random pattern, catching and dropping out, then they all burn bright */
const SCHED = BULBS.map(() => { const segs = []; let t = Math.random() * .25;
  while (t < FLK) { const u = t / FLK, on = Math.random() < .14 + .72 * Math.pow(u, 1.25), len = .04 + Math.random() * (on ? .16 : .12); segs.push([t, t + len, on ? .45 + Math.random() * .55 : 0]); t += len; }
