function sparkle(n, spread){
  const col = Math.min(innerWidth, document.querySelector(".inv").getBoundingClientRect().width), x0 = (innerWidth - col) / 2;
  for (let i = 0; i < n; i++) bits.push({ x: x0 + Math.random() * col, y: -12 - Math.random() * innerHeight * (spread || .4), vx: (Math.random() - .5) * 18, vy: 30 + Math.random() * 42, s: 1.5 + Math.random() * 2.4, ph: Math.random() * 6.3, c: ["#FFE3A6", "#F6C36E", "#FFF4DA", "#F2C9A8"][i % 4] });
  if (bits.length > 200) bits.splice(0, bits.length - 200);
